create or replace function public.marcar_processo_ja_existente() returns trigger language plpgsql set search_path = '' as $function$ declare v_numero text; v_referencia date; begin if new.duplicado then return new; end if; v_numero := upper(regexp_replace(new.numero_processo, '[^0-9A-Za-z]', '', 'g')); if v_numero is null or v_numero = '' then return new; end if; v_referencia := coalesce(new.data_referencia, new.data_disponibilizacao, (coalesce(new.created_at, now()) at time zone 'America/Sao_Paulo')::date); select exists (select 1 from public.intimacoes i where i.numero_processo_normalizado = v_numero and i.data_referencia < v_referencia) into new.duplicado; return new; end; $function$